import { test, expect } from '@playwright/test';

test.describe('Pagination Controls', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    // Wait for the page to load and pagination controls to be visible
    await page.waitForLoadState('networkidle');
  });

  test('should load first page of results by default', async ({ page }) => {
    // Verify that the first page is loaded
    const firstPageButton = page.getByRole('button', { name: /page 1/i });
    await expect(firstPageButton).toHaveAttribute('aria-current', 'page');

    // Verify that results are displayed
    const resultItems = page.getByRole('listitem');
    const itemCount = await resultItems.count();
    expect(itemCount).toBeGreaterThan(0);

    // Verify that the first result is from page 1
    const firstResult = page.getByRole('listitem').first();
    await expect(firstResult).toBeVisible();
  });

  test('should navigate to next page when next button is clicked', async ({ page }) => {
    // Get the first result text from page 1
    const firstPageFirstResult = await page.getByRole('listitem').first().textContent();

    // Click the next page button
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();

    // Wait for the page to load
    await page.waitForLoadState('networkidle');

    // Verify that page 2 is now active
    const secondPageButton = page.getByRole('button', { name: /page 2/i });
    await expect(secondPageButton).toHaveAttribute('aria-current', 'page');

    // Verify that results have changed
    const secondPageFirstResult = await page.getByRole('listitem').first().textContent();
    expect(secondPageFirstResult).not.toBe(firstPageFirstResult);
  });

  test('should navigate to specific page when page number is clicked', async ({ page }) => {
    // Click on page 3
    const pageThreeButton = page.getByRole('button', { name: /page 3/i });
    await pageThreeButton.click();

    // Wait for the page to load
    await page.waitForLoadState('networkidle');

    // Verify that page 3 is now active
    await expect(pageThreeButton).toHaveAttribute('aria-current', 'page');

    // Verify that results are displayed
    const resultItems = page.getByRole('listitem');
    const itemCount = await resultItems.count();
    expect(itemCount).toBeGreaterThan(0);
  });

  test('should navigate to previous page when previous button is clicked', async ({ page }) => {
    // Navigate to page 2 first
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();
    await page.waitForLoadState('networkidle');

    // Get the first result text from page 2
    const secondPageFirstResult = await page.getByRole('listitem').first().textContent();

    // Click the previous button
    const prevButton = page.getByRole('button', { name: /previous/i });
    await prevButton.click();

    // Wait for the page to load
    await page.waitForLoadState('networkidle');

    // Verify that page 1 is now active
    const firstPageButton = page.getByRole('button', { name: /page 1/i });
    await expect(firstPageButton).toHaveAttribute('aria-current', 'page');

    // Verify that results have changed back to page 1
    const firstPageFirstResult = await page.getByRole('listitem').first().textContent();
    expect(firstPageFirstResult).not.toBe(secondPageFirstResult);
  });

  test('should disable previous button on first page', async ({ page }) => {
    // Verify that previous button is disabled on first page
    const prevButton = page.getByRole('button', { name: /previous/i });
    await expect(prevButton).toBeDisabled();
  });

  test('should disable next button on last page', async ({ page }) => {
    // Get the total number of pages
    const pageButtons = page.getByRole('button', { name: /page \d+/i });
    const pageCount = await pageButtons.count();

    // Navigate to the last page
    const lastPageButton = page.getByRole('button', { name: new RegExp(`page ${pageCount}`) });
    await lastPageButton.click();
    await page.waitForLoadState('networkidle');

    // Verify that next button is disabled on last page
    const nextButton = page.getByRole('button', { name: /next/i });
    await expect(nextButton).toBeDisabled();
  });

  test('should display correct page information', async ({ page }) => {
    // Check for page information display (e.g., "Page 1 of 5")
    const pageInfo = page.getByText(/page \d+ of \d+/i);
    await expect(pageInfo).toBeVisible();

    // Navigate to page 2
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();
    await page.waitForLoadState('networkidle');

    // Verify that page info has updated
    const updatedPageInfo = page.getByText(/page 2 of \d+/i);
    await expect(updatedPageInfo).toBeVisible();
  });

  test('should maintain results per page setting when navigating', async ({ page }) => {
    // Get the number of items on page 1
    const firstPageItems = await page.getByRole('listitem').count();

    // Navigate to page 2
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();
    await page.waitForLoadState('networkidle');

    // Get the number of items on page 2
    const secondPageItems = await page.getByRole('listitem').count();

    // Verify that the number of items per page is consistent
    expect(secondPageItems).toBe(firstPageItems);
  });

  test('should handle rapid pagination clicks correctly', async ({ page }) => {
    // Click next button multiple times rapidly
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();
    await nextButton.click();
    await nextButton.click();

    // Wait for the final page load
    await page.waitForLoadState('networkidle');

    // Verify that we're on page 4
    const pageFourButton = page.getByRole('button', { name: /page 4/i });
    await expect(pageFourButton).toHaveAttribute('aria-current', 'page');

    // Verify that results are displayed
    const resultItems = page.getByRole('listitem');
    const itemCount = await resultItems.count();
    expect(itemCount).toBeGreaterThan(0);
  });
});
